using System;
using AudioEdit.sfx;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Media;
using MonsterEdit.monsters;
using ProjectTower.character;
using ProjectTower.config;
using ProjectTower.debug;
using ProjectTower.gamestate;
using ProjectTower.map;
using ProjectTower.player;

namespace ProjectTower.audio;

public class Music
{
	public const int TRACK_DREAD = 0;

	public const int TRACK_SHRINE = 1;

	public const int TRACK_MOODS = 2;

	public const int TRACK_GIT_CHIME = 3;

	public const int TRACK_SYNTH_MOOD = 4;

	public const int TRACK_DRONE = 5;

	public const int TRACK_TERROR = 6;

	public const int TRACK_SHIMMER = 7;

	public const int TRACK_CREDITS = 8;

	public const int TRACK_FINAL = 9;

	public const int TRACK_CATHEDRAL = 10;

	public const int TOTAL_TRACKS = 11;

	public static Track[] library;

	public static MgrSoundBank musicSnd;

	private static int currentTrack;

	private static int goalTrack;

	public const string MUSIC = "Music";

	public const string FILTER = "Filter";

	private static float vol;

	public static bool isInited;

	public static bool isReady;

	public static float ambientFrame;

	public static int debugMasterVol;

	private static float musicVol;

	private static MediaState mediaState;

	public static void Init()
	{
		MediaPlayer.MediaStateChanged += MediaPlayer_MediaStateChanged;
		library = new Track[11];
		library[0] = new Track("dread", mood: false, alwaysStart: true);
		library[1] = new Track("shrine", mood: false, alwaysStart: true);
		library[2] = new Track("moods", mood: true, alwaysStart: false);
		library[3] = new Track("gitchime", mood: true, alwaysStart: false);
		library[4] = new Track("synthmood", mood: true, alwaysStart: false);
		library[5] = new Track("raindrone", mood: false, alwaysStart: false);
		library[6] = new Track("terror", mood: false, alwaysStart: true);
		library[7] = new Track("shimmer", mood: false, alwaysStart: true);
		library[8] = new Track("credits", mood: false, alwaysStart: true);
		library[9] = new Track("final", mood: false, alwaysStart: true);
		library[10] = new Track("cathedral", mood: false, alwaysStart: true);
		Sound.Update();
		currentTrack = -1;
		goalTrack = -1;
		vol = 0f;
		debugMasterVol = 100;
		isInited = true;
	}

	private static void MediaPlayer_MediaStateChanged(object sender, EventArgs e)
	{
		mediaState = MediaPlayer.State;
	}

	public static void SetMusic(string s)
	{
		if (s == "-1")
		{
			SetMusic(-1);
		}
		for (int i = 0; i < library.Length; i++)
		{
			if (library[i].name == s)
			{
				SetMusic(i);
				break;
			}
		}
	}

	public static void SetMusic(int i)
	{
		goalTrack = i;
	}

	internal static void UpdateMusicVolume()
	{
		SetMusicVolume(vol);
	}

	internal static void SetMusicVolume(float vol)
	{
		MediaPlayer.Volume = vol * ((float)debugMasterVol / 100f) * ((float)ConfigMgr.bgm / 10f);
	}

	public static void Update(float frameTime, float realTime)
	{
		if (!isInited)
		{
			return;
		}
		int num = -1;
		Character mainCharacter = GameStateManager.GetMainCharacter();
		Character character = mainCharacter;
		if (GameStateManager.coopPlayerIdx > -1)
		{
			Player coopPlayer = PlayerMgr.GetCoopPlayer();
			if (coopPlayer != null)
			{
				character = CharMgr.GetPlayerCharacter(coopPlayer);
			}
		}
		if (mainCharacter != null)
		{
			int sanctuaryIn = MapMgr.sanctuaryMgr.GetSanctuaryIn((mainCharacter.hp <= 0f && GameStateManager.coopPlayerIdx > -1) ? character : mainCharacter);
			if (sanctuaryIn > -1 && MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].creed != 0 && !MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].shrine && !(MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].desecrationFrame > 0f))
			{
				num = 1;
			}
			int layer = CharCols.GetLayer(mainCharacter.loc + new Vector2(0f, -16f));
			if ((uint)(layer - 21) <= 2u)
			{
				num = 10;
			}
			int cannedArenaIdx = MapMgr.map.triggerMgr.GetCannedArenaIdx((mainCharacter.hp <= 0f && GameStateManager.coopPlayerIdx > -1) ? character : mainCharacter);
			if (cannedArenaIdx > -1 && MapMgr.map.triggerMgr.GetAnyArenaBossIdx(cannedArenaIdx) && BossToast.confirmedOkay)
			{
				num = 0;
				int arenaBossIdx = MapMgr.map.triggerMgr.GetArenaBossIdx(cannedArenaIdx, 0);
				if (arenaBossIdx > -1)
				{
					switch (MonsterCatalog.catalog[CharMgr.character[arenaBossIdx].monsterIdx].defIdx)
					{
					case 3:
					case 20:
					case 29:
					case 34:
					case 54:
					case 62:
					case 75:
					case 76:
					case 97:
						num = 6;
						break;
					case 92:
						num = 9;
						break;
					default:
						num = 0;
						break;
					}
				}
			}
			if (GameStateManager.wordsFrame > 0f && GameStateManager.wordsMode == 1)
			{
				num = -1;
			}
		}
		for (int i = 0; i < PlayerMgr.player.Length; i++)
		{
			if (PlayerMgr.player[i].active && PlayerMgr.player[i].camMgr.scarecrowfreak > 0.5f)
			{
				num = 5;
			}
		}
		ambientFrame += frameTime;
		if (num == -1 && goalTrack > -1 && library[goalTrack].mood)
		{
			num = goalTrack;
		}
		if (ambientFrame > 60f)
		{
			int num2 = 0;
			if (mainCharacter != null)
			{
				num2 = CharCols.GetLayer(mainCharacter.loc + new Vector2(0f, -16f));
			}
			if (num == -1 && GameStateManager.gameState == 1)
			{
				bool flag = true;
				if ((uint)(num2 - 6) <= 1u)
				{
					flag = false;
				}
				if (flag)
				{
					switch (Rand.GetRandomInt(0, 3))
					{
					case 0:
						num = 2;
						break;
					case 1:
						num = 3;
						break;
					case 2:
						num = 4;
						break;
					}
				}
			}
			ambientFrame = Rand.GetRandomFloat(-240f, -200f);
		}
		if (DebugMgr.vidMode != 0)
		{
			num = -1;
		}
		switch (GameStateManager.gameState)
		{
		case 4:
			num = 8;
			GameStateManager.endGameMusicFrame = 0f;
			break;
		default:
			num = -1;
			GameStateManager.endGameMusicFrame = 0f;
			break;
		case 1:
			break;
		}
		if (GameStateManager.endGameMusicFrame > 0f)
		{
			num = 7;
			GameStateManager.endGameMusicFrame += realTime;
			EndGameMgr.UpdateWisps();
		}
		SetMusic(num);
		float num3 = 1f;
		if (goalTrack != currentTrack)
		{
			switch (mediaState)
			{
			case MediaState.Playing:
				vol -= frameTime * num3;
				if (vol <= 0f || (goalTrack > -1 && library[goalTrack].alwaysStart))
				{
					if (goalTrack > -1 && library[goalTrack].alwaysStart)
					{
						vol = 1f;
					}
					MediaPlayer.Stop();
					currentTrack = goalTrack;
					if (currentTrack > -1)
					{
						musicSnd.PlayCue(library[currentTrack].name);
						musicVol = musicSnd.GetVol(library[currentTrack].name);
						SetMusicVolume(vol * musicVol);
					}
				}
				else
				{
					SetMusicVolume(vol * musicVol);
				}
				break;
			case MediaState.Stopped:
				currentTrack = goalTrack;
				if (currentTrack > -1)
				{
					musicSnd.PlayCue(library[currentTrack].name);
					musicVol = musicSnd.GetVol(library[currentTrack].name);
					SetMusicVolume(vol * musicVol);
				}
				break;
			}
			return;
		}
		if (mediaState != MediaState.Playing)
		{
			currentTrack = (goalTrack = -1);
		}
		if (vol < 1f)
		{
			vol += frameTime * num3;
			if (vol > 1f)
			{
				vol = 1f;
			}
		}
		SetMusicVolume(vol * musicVol);
	}
}

using System.Collections.Generic;
using AudioEdit.sfx;
using MapEdit;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Audio;
using Microsoft.Xna.Framework.Content;
using ProjectTower.character;
using ProjectTower.gamestate;
using ProjectTower.player;

namespace ProjectTower.audio;

public class Sound
{
	private struct Cue3D
	{
		public SoundEffectInstance cue;

		public Vector2 loc;

		internal void Update()
		{
			Vector2 vector = loc;
			if (GameStateManager.coopPlayerIdx > -1)
			{
				vector.X = (PlayerMgr.GetMainPlayer().camMgr.scroll.X + PlayerMgr.GetCoopPlayer().camMgr.scroll.X) / 2f;
			}
			else
			{
				vector.X = ScrollManager.scroll.X;
			}
			float num = (loc.X - vector.X) / 1280f;
			if (num > 1f)
			{
				num = 1f;
			}
			if (num < -1f)
			{
				num = -1f;
			}
			if (num >= -1f && num <= 1f)
			{
				cue.Pan = num;
			}
		}

		internal void Set(SoundEffectInstance cue, Vector2 loc)
		{
			if (this.cue != null)
			{
				this.cue.Dispose();
			}
			this.cue = cue;
			this.loc = loc;
		}
	}

	private struct CategorySoundInstance
	{
		public float gVol;

		public SoundEffectInstance instance;
	}

	private struct Spre
	{
		private string name;

		private float wait;

		private float maxWait;

		public void Init(string _name, float _wait)
		{
			name = _name;
			maxWait = _wait;
		}

		public void Update()
		{
			if (wait > 0f)
			{
				wait -= Game1.frameTime;
			}
		}

		public void Play()
		{
			if (wait <= 0f)
			{
				int cueIdx = sound.GetCueIdx(name);
				if (cueIdx > -1 && !PlayCategory(cueIdx))
				{
					sound.PlayCue(cueIdx);
				}
				wait = maxWait;
			}
		}

		public void Play(Vector2 loc, int range)
		{
			if (name == "drips")
			{
				GameConsole.WriteLine(wait.ToString());
			}
			if (wait <= 0f)
			{
				Play3DSound(name, loc, range);
				wait = maxWait;
			}
		}
	}

	public const int SPRE_WAVES = 0;

	public const int SPRE_SMALL_WAVES = 1;

	public const int SPRE_SMALL_WAVES_2 = 2;

	public const int SPRE_TORCH = 3;

	public const int SPRE_CHIMES = 4;

	public const int SPRE_STORM = 5;

	public const int SPRE_RAIN = 6;

	public const int SPRE_RAIN_IN = 7;

	public const int SPRE_CREAK = 8;

	public const int SPRE_CAVE = 9;

	public const int SPRE_CAVE_DRIPS = 10;

	public const int SPRE_RAIN_DRIPS = 11;

	public const int SPRE_BUGS = 12;

	public const int SPRE_LIGHT_RAIN = 13;

	public const int SPRE_DUNGEON = 14;

	public const int SPRE_RED_CHAINS = 15;

	public const int SPRE_FLAMEJET_START = 16;

	public const int SPRE_FLAMEJET_BIT = 17;

	public const int SPRE_TRICKLE = 18;

	public const int SPRE_STREAM = 19;

	public const int TOTAL_SPRES = 20;

	private static Spre[] spres;

	public const int RANGE_CLOSE = 0;

	public const int RANGE_FAR = 1;

	public const int RANGE_CLOSE_ANY_LAYER = 2;

	public const float MAX_DIST = 5000000f;

	private static SoundManager sndMgr;

	private static MgrSoundBank sound;

	private static MgrSoundBank voxSound;

	private static Cue3D[] cueBank;

	private static CategorySoundInstance[,] categorySoundInstances;

	private const int TOTAL_CATEGORY_INSTANCES = 16;

	private static AudioCategory[] cats;

	private const int CAT_OUTDOORS = 0;

	private const int CAT_INDOORS = 1;

	private const int TOTAL_CATS = 2;

	public static void Init(ContentManager Content)
	{
		sndMgr = new SoundManager();
		sndMgr.Read(Content);
		sound = sndMgr.GetSoundBank("sfx");
		voxSound = sndMgr.GetSoundBank("vox");
		Music.musicSnd = sndMgr.GetSoundBank("music");
		spres = new Spre[20];
		spres[0].Init("waves", 3f);
		spres[1].Init("smallwaves", 3f);
		spres[2].Init("smallwaves", 3.2f);
		spres[3].Init("torch", 3f);
		spres[4].Init("chimes", 3f);
		spres[5].Init("storm", 3f);
		spres[6].Init("rain", 3.05f);
		spres[7].Init("rainin", 3.1f);
		spres[8].Init("creak", 3.15f);
		spres[9].Init("cave", 3.15f);
		spres[10].Init("drips", 3.15f);
		spres[13].Init("lightrain", 3.15f);
		spres[11].Init("raindrips", 3.15f);
		spres[12].Init("bugs", 3.15f);
		spres[14].Init("dungeon", 3.15f);
		spres[15].Init("dchains", 3.15f);
		spres[16].Init("flamejetstart", 0.35f);
		spres[17].Init("flamejetbit", 0.35f);
		spres[18].Init("trickle", 2.5f);
		spres[19].Init("stream", 2.5f);
		cueBank = new Cue3D[64];
		categorySoundInstances = new CategorySoundInstance[2, 16];
	}

	public static void Play3DSound(string name, Vector2 loc, int range)
	{
		if (range == 0)
		{
			int layer = CharCols.GetLayer(loc + new Vector2(0f, -16f));
			if (GameStateManager.mainPlayerIdx > -1 && layer != PlayerMgr.player[GameStateManager.mainPlayerIdx].camMgr.curLayer)
			{
				return;
			}
		}
		if (GameStateManager.coopPlayerIdx > -1)
		{
			if (range == 0)
			{
				Player mainPlayer = PlayerMgr.GetMainPlayer();
				Player coopPlayer = PlayerMgr.GetCoopPlayer();
				if (mainPlayer == null || coopPlayer == null || ((loc.X < mainPlayer.camMgr.tL.X - 200f || loc.Y < mainPlayer.camMgr.tL.Y - 200f || loc.X > mainPlayer.camMgr.bR.X + 200f || loc.Y > mainPlayer.camMgr.bR.Y + 200f) && (loc.X < coopPlayer.camMgr.tL.X - 200f || loc.Y < coopPlayer.camMgr.tL.Y - 200f || loc.X > coopPlayer.camMgr.bR.X + 200f || loc.Y > coopPlayer.camMgr.bR.Y + 200f)))
				{
					return;
				}
			}
		}
		else if (range == 0 && (loc.X < ScrollManager.tL.X - 200f || loc.Y < ScrollManager.tL.Y - 200f || loc.X > ScrollManager.bR.X + 200f || loc.Y > ScrollManager.bR.Y + 200f))
		{
			return;
		}
		for (int i = 0; i < cueBank.Length; i++)
		{
			if (cueBank[i].cue == null)
			{
				int cueIdx = sound.GetCueIdx(name);
				if (cueIdx > -1)
				{
					cueBank[i].Set(sound.GetCue(cueIdx), loc);
					if (cueBank[i].cue != null)
					{
						cueBank[i].cue.Volume = sound.GetVol(cueIdx);
						cueBank[i].cue.Pitch = sound.GetPitch(cueIdx);
						cueBank[i].Update();
						cueBank[i].cue.Play();
					}
				}
				break;
			}
			if (cueBank[i].cue.State == SoundState.Playing)
			{
				continue;
			}
			int cueIdx2 = sound.GetCueIdx(name);
			if (cueIdx2 > -1)
			{
				cueBank[i].Set(sound.GetCue(cueIdx2), loc);
				if (cueBank[i].cue != null)
				{
					cueBank[i].cue.Volume = sound.GetVol(cueIdx2);
					cueBank[i].cue.Pitch = sound.GetPitch(cueIdx2);
					cueBank[i].Update();
					cueBank[i].cue.Play();
				}
			}
			break;
		}
	}

	public static void PlaySnd(string name)
	{
		int cueIdx = sound.GetCueIdx(name);
		if (cueIdx > -1 && !PlayCategory(cueIdx))
		{
			sound.PlayCue(cueIdx);
		}
	}

	private static bool PlayCategory(int idx)
	{
		int category = sound.GetCategory(idx);
		if (category > -1)
		{
			for (int i = 0; i < 16; i++)
			{
				bool flag = false;
				if (categorySoundInstances[category, i].instance == null)
				{
					flag = true;
				}
				else if (categorySoundInstances[category, i].instance.State != SoundState.Playing)
				{
					flag = true;
				}
				if (flag)
				{
					if (categorySoundInstances[category, i].instance != null)
					{
						categorySoundInstances[category, i].instance.Dispose();
					}
					categorySoundInstances[category, i].instance = sound.GetCue(idx);
					if (categorySoundInstances[category, i].instance == null)
					{
						return true;
					}
					categorySoundInstances[category, i].gVol = sound.GetVol(idx);
					categorySoundInstances[category, i].instance.Volume = 0f;
					categorySoundInstances[category, i].instance.Play();
					return true;
				}
			}
		}
		return false;
	}

	public static void PlayVox(string name)
	{
		if (name != null && !(name == ""))
		{
			voxSound.PlayCue(name);
		}
	}

	public static void Update()
	{
		if (spres == null)
		{
			return;
		}
		for (int i = 0; i < 20; i++)
		{
			spres[i].Update();
		}
		for (int j = 0; j < cueBank.Length; j++)
		{
			if (cueBank[j].cue != null && cueBank[j].cue.State == SoundState.Playing)
			{
