	private bool idxSet;

	public int selSnd;

	public BankCue()
	{
		bankSnd = new List<string>();
	}

	public void Read(BinaryReader reader)
	{
		name = reader.ReadString();
		bankSnd = new List<string>();
		int num = reader.ReadInt32();
		for (int i = 0; i < num; i++)
		{
			bankSnd.Add(reader.ReadString());
		}
	}

	internal void SetIdx(SoundManager sndMgr, MgrSoundBank sndBank)
	{
		bankSndIdx = new int[bankSnd.Count];
		for (int i = 0; i < bankSnd.Count; i++)
		{
			bankSndIdx[i] = -1;
			for (int j = 0; j < sndBank.bankSound.Length; j++)
			{
				if (sndBank.bankSound[j].name == bankSnd[i])
				{
					bankSndIdx[i] = j;
				}
			}
		}
		idxSet = true;
	}

	internal void Play(SoundManager sndMgr, MgrSoundBank sndBank)
	{
		if (!idxSet)
		{
			SetIdx(sndMgr, sndBank);
		}
		selSnd = ((bankSnd.Count > 1) ? Rand.GetRandomInt(0, bankSnd.Count) : 0);
		if (bankSndIdx[selSnd] > -1)
		{
			sndBank.bankSound[bankSndIdx[selSnd]].Play(sndMgr);
		}
	}

	internal float GetVol(SoundManager sndMgr, MgrSoundBank sndBank)
	{
		if (!idxSet)
		{
			SetIdx(sndMgr, sndBank);
		}
		if (bankSndIdx[selSnd] > -1)
		{
			return sndBank.bankSound[bankSndIdx[selSnd]].volume * ((float)ConfigMgr.sfx / 10f);
		}
		return 0f;
	}

	internal float GetPitch(SoundManager sndMgr, MgrSoundBank sndBank)
	{
		if (!idxSet)
		{
			SetIdx(sndMgr, sndBank);
		}
		if (bankSndIdx[selSnd] > -1)
		{
			return sndBank.bankSound[bankSndIdx[selSnd]].pitch;
		}
		return 0f;
	}

	internal SoundEffectInstance GetInstance(SoundManager sndMgr, MgrSoundBank sndBank)
	{
		if (!idxSet)
		{
			SetIdx(sndMgr, sndBank);
		}
		selSnd = Rand.GetRandomInt(0, bankSnd.Count);
		if (bankSndIdx[selSnd] > -1)
		{
			return sndBank.bankSound[bankSndIdx[selSnd]].GetInstance(sndMgr);
		}
		return null;
	}

	internal void Play(SoundManager sndMgr, MgrSoundBank sndBank, float volume, float pan)
	{
		if (!idxSet)
		{
			SetIdx(sndMgr, sndBank);
		}
		selSnd = Rand.GetRandomInt(0, bankSnd.Count);
		if (bankSndIdx[selSnd] > -1)
		{
			sndBank.bankSound[bankSndIdx[selSnd]].Play(sndMgr, volume, pan);
		}
	}

