	{
		for (int i = 0; i < soundBank.Length; i++)
		{
			if (!(soundBank[i].title == bank))
			{
				continue;
			}
			for (int j = 0; j < soundBank[i].bankCue.Length; j++)
			{
				if (soundBank[i].bankCue[j].name == cue)
				{
					soundBank[i].bankCue[j].Play(this, soundBank[i]);
				}
			}
		}
	}

	public MgrSoundBank GetSoundBank(string name)
	{
		for (int i = 0; i < soundBank.Length; i++)
		{
			if (soundBank[i].title == name)
			{
				return soundBank[i];
			}
		}
		return null;
	}

	internal void Read(ContentManager Content)
	{
		BinaryReader binaryReader = new BinaryReader(File.Open("audio/sfx/data/sfx.zxp", FileMode.Open, FileAccess.Read));
